export class ActionFormData {
  constructor() { this.buttons = []; }
  title(t) { this.titleText = t; return this; }
  body(b) { this.bodyText = b; return this; }
  button(l) { this.buttons.push(l); return this; }
  show() { return Promise.resolve({ canceled: true }); }
}
export class ModalFormData extends ActionFormData {}
export class MessageFormData extends ActionFormData {}
